CREATE TABLE commercial_ledger_mappings (company_id UUID PRIMARY KEY REFERENCES companies(id) ON DELETE CASCADE,cash_account_id UUID REFERENCES accounting_accounts(id) ON DELETE SET NULL,receivable_account_id UUID REFERENCES accounting_accounts(id) ON DELETE SET NULL,payable_account_id UUID REFERENCES accounting_accounts(id) ON DELETE SET NULL,revenue_account_id UUID REFERENCES accounting_accounts(id) ON DELETE SET NULL,expense_account_id UUID REFERENCES accounting_accounts(id) ON DELETE SET NULL,updated_by UUID REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE commercial_documents ADD COLUMN journal_id UUID REFERENCES accounting_journals(id) ON DELETE SET NULL;
ALTER TABLE commercial_payments ADD COLUMN journal_id UUID REFERENCES accounting_journals(id) ON DELETE SET NULL;
ALTER TABLE pos_sales ADD COLUMN refunded_at TIMESTAMPTZ, ADD COLUMN refunded_by UUID REFERENCES users(id) ON DELETE SET NULL, ADD COLUMN refund_note TEXT NOT NULL DEFAULT '' CHECK(length(refund_note)<=1000);
